from PIL import Image
im = Image.open('r153-dots-light.png').convert('RGB')
px = im.load()
# census of colored pixels (saturation: max-min channel > 30) in top band y0..29
cols = {}
for y in range(0, 30):
    for x in range(1000, 1100):
        r,g,b = px[x,y]
        if max(r,g,b) - min(r,g,b) > 30:
            cols.setdefault((r,g,b), []).append((x,y))
# group by approximate color
groups = {}
for c, pts in cols.items():
    key = (c[0]//40, c[1]//40, c[2]//40)
    groups.setdefault(key, []).append((c, pts))
for key, lst in sorted(groups.items(), key=lambda kv: -len(kv[1])):
    xs = [p[0] for _,pts in lst for p in pts]; ys=[p[1] for _,pts in lst for p in pts]
    print(f"group~{tuple(k*40 for k in key)} count={sum(len(p) for _,p in lst)} x{min(xs)}..{max(xs)} y{min(ys)}..{max(ys)}")
    # dominant exact colors
    from collections import Counter
    cc = Counter(c for c,pts in lst for _ in pts)
    for col,n in cc.most_common(3):
        print("   color", col, "n", n)
EOF

